function check(input, actual, expected) {
  const [n, k] = input;
  if (!Array.isArray(actual) || actual.length !== n) return false;
  const used = new Array(n + 1).fill(false);
  for (const value of actual) {
    if (!Number.isInteger(value) || value < 1 || value > n || used[value]) return false;
    used[value] = true;
  }
  const gaps = new Set();
  for (let i = 1; i < n; i++) gaps.add(Math.abs(actual[i] - actual[i - 1]));
  return gaps.size === k;
}

