function validate([n, k]) {
  if (!Number.isInteger(n) || !Number.isInteger(k)) return 'n and k must be whole numbers.';
  if (n < 2 || n > 10000) return 'n is between 2 and 10^4 (k must be at least 1 and below n).';
  if (k < 1 || k >= n) return 'k is at least 1 and less than n.';
  return null;
}

