function constructArray(n, k) {
  const answer = [];
  for (let value = 1; value < n - k; value++) {
    answer.push(value);
  }

  let low = n - k;
  let high = n;
  let takeLow = true;
  while (low <= high) {
    if (takeLow) {
      answer.push(low);
      low++;
    } else {
      answer.push(high);
      high--;
    }
    takeLow = !takeLow;
  }
  return answer;
}

