function constructArray(n, k) {
  // Zigzag at the front instead: from 1, step by +k, -(k-1), +(k-2), ... down to 1, then count up from k + 2.
  const order = [1];
  let sign = 1;
  for (let gap = k; gap >= 1; gap--) {
    order.push(order[order.length - 1] + sign * gap);
    sign = -sign;
  }
  for (let v = k + 2; v <= n; v++) order.push(v);
  return order;
}

